//! An example of using perlin noise

extern mod noise;

use std::uint::range;
use noise::perlin::*;

static WIDTH: uint = 100;
static HEIGHT: uint = 100;

static GRADIENT: [&'static str, ..6] = [" ", "░", "▒", "▓", "█", "█"];

fn main() {
    let ctx = PerlinContext::new::<f32>();

    for range(0, HEIGHT) |y| {
        for range(0, WIDTH) |x| {
