#[derive(Debug, PartialEq)]
pub enum Type {
    JSON,
    XML,
    Ruby
}

pub fn from_path(path: &Path) -> Option<Type> {
    match path.to_str() {
        Some(filename) => {
            let extension = filename.split('.').last();
            match extension {
                Some("json") => Some(Type::JSON),
                Some("xml") => Some(Type::XML),
                Some("rb") => Some(Type::Ruby),
                _ => None,
            }
        },
        None => return None,
    }
